`,VR=`/**
 * Leaky bucket: requests enter a queue and drain at a CONSTANT rate.
 *
 * Contrast with token bucket, which lets a saved-up burst through instantly.
 * Leaky bucket smooths output no matter how bursty the input is.
 */
export class LeakyBucket {
  constructor({ capacity = 5, leakRatePerSec = 2 } = {}) {
    this.capacity = capacity
    this.intervalMs = 1000 / leakRatePerSec
    this.queue = []
    this.timer = null
  }

  /** Returns false when the bucket is full -- the request is DROPPED. */
  add(item, onLeak) {
    if (this.queue.length >= this.capacity) return false
    this.queue.push({ item, onLeak })
    this.#start()
    return true
  }

  #start() {
    if (this.timer !== null) return
    this.timer = setInterval(() => {
      const next = this.queue.shift()
      if (!next) { clearInterval(this.timer); this.timer = null; return }
      next.onLeak(next.item)
    }, this.intervalMs)
  }

  stop() { clearInterval(this.timer); this.timer = null }
  get size() { return this.queue.length }
}
`,YR=`/**
 * LRU cache with O(1) get and put.
 *
 * Uses a JS Map, which guarantees INSERTION ORDER -- so the first key from
 * map.keys() is the least recently used, provided we re-insert on every
 * access. That removes the need to hand-roll a doubly linked list.
 */
export class LRUCache {
  constructor(capacity) {
    this.capacity = capacity
    this.map = new Map()
  }

  get(key) {
    if (!this.map.has(key)) return -1
    const value = this.map.get(key)
    // Re-insert to move this key to the most-recent end.
    this.map.delete(key)
    this.map.set(key, value)
    return value
  }

  put(key, value) {
    // Delete first so an update also moves the key to the recent end.
    if (this.map.has(key)) this.map.delete(key)
    this.map.set(key, value)

    if (this.map.size > this.capacity) {
      const oldest = this.map.keys().next().value
      this.map.delete(oldest)
    }
  }
}
