const results = []
results.push(['slowAdd(1,2)', slowAdd(1, 2), calls])
results.push(['slowAdd(1,2) again (cached)', slowAdd(1, 2), calls])
results.push(['slowAdd(2,1) different args', slowAdd(2, 1), calls])

