import { Trie } from './Trie.js'

const WORDS = ['car','card','care','careful','cat','cats','dog','dodge','door','do','done']

export default function Demo() {
  const trie = useMemo(() => {
    const t = new Trie()
    WORDS.forEach((w) => t.insert(w))
    return t
  }, [])
  const [prefix, setPrefix] = useState('ca')

  const matches = trie.autocomplete(prefix)

  return (
    <div>
      <input value={prefix} onChange={(e) => setPrefix(e.target.value)}
             placeholder="prefix…" style={{ padding: 8, fontSize: 15, width: 220 }} />
      <table style={{ borderCollapse: 'collapse', fontFamily: 'monospace', fontSize: 13, marginTop: 14 }}>
        <tbody>
          <tr><td style={{ padding: '5px 18px 5px 0' }}>autocomplete("{prefix}")</td>
              <td style={{ fontWeight: 700 }}>{matches.length ? matches.join(', ') : '—'}</td></tr>
          <tr><td style={{ padding: '5px 18px 5px 0' }}>search("{prefix}") — exact word?</td>
              <td style={{ fontWeight: 700 }}>{String(trie.search(prefix))}</td></tr>
          <tr><td style={{ padding: '5px 18px 5px 0' }}>startsWith("{prefix}")</td>
              <td style={{ fontWeight: 700 }}>{String(trie.startsWith(prefix))}</td></tr>
        </tbody>
      </table>
      <p style={{ color: '#666', fontSize: 13 }}>
        Try “car” — it is both a stored word and a prefix of others.
      </p>
    </div>
  )
}
`,EO=`/**
 * Trie (prefix tree). Every node is one character; a path from the root spells
 * a prefix. \`count\` (words passing through) is what makes delete O(m) without
 * a second traversal to check whether a branch is still needed.
 */
class TrieNode {
  constructor() {
    this.children = new Map()
    this.isEnd = false
    this.count = 0
  }
}

export class Trie {
  constructor() { this.root = new TrieNode() }

  /** O(m) where m = word length -- independent of how many words are stored. */
  insert(word) {
    let node = this.root
    for (const char of word) {
      if (!node.children.has(char)) node.children.set(char, new TrieNode())
      node = node.children.get(char)
      node.count++
    }
    node.isEnd = true
  }

  #traverse(prefix) {
    let node = this.root
    for (const char of prefix) {
      node = node.children.get(char)
      if (!node) return null
    }
    return node
  }

  /** Exact word -- isEnd distinguishes a stored word from a mere prefix. */
  search(word) { return this.#traverse(word)?.isEnd ?? false }

  startsWith(prefix) { return this.#traverse(prefix) !== null }

  /** All words sharing a prefix -- the autocomplete operation. */
  autocomplete(prefix, limit = 10) {
    const node = this.#traverse(prefix)
    if (!node) return []
    const out = []
    const walk = (n, acc) => {
      if (out.length >= limit) return
      if (n.isEnd) out.push(acc)
      for (const [char, child] of n.children) walk(child, acc + char)
    }
    walk(node, prefix)
    return out
  }

  delete(word) {
    if (!this.search(word)) return false
    let node = this.root
    for (const char of word) {
      const child = node.children.get(char)
      child.count--
      // No other word passes through here -- prune the whole branch.
      if (child.count === 0) { node.children.delete(char); return true }
      node = child
    }
    node.isEnd = false
    return true
  }
}
